#!/usr/bin/env python3
"""Merge user records from three sources, resolving conflicts by priority.

Priority: source_a > source_b > source_c.
Unified schema: user_id (int), name (str), email (str),
created_date (str, YYYY-MM-DD), status (str, optional).
"""

import json

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

# (source name, path, reader kind, {source column -> unified column})
SOURCES = [
    (
        "source_a",
        "/data/source_a/users.json",
        "json",
        {
            "id": "user_id",
            "full_name": "name",
            "email": "email",
            "registration_date": "created_date",
            "status": "status",
        },
    ),
    (
        "source_b",
        "/data/source_b/users.csv",
        "csv",
        {
            "user_id": "user_id",
            "name": "name",
            "email_address": "email",
            "created_at": "created_date",
            "is_active": "status",
        },
    ),
    (
        "source_c",
        "/data/source_c/users.parquet",
        "parquet",
        {
            "userId": "user_id",
            "userName": "name",
            "email": "email",
            "joined": "created_date",
            "active": "status",
        },
    ),
]

FIELDS = ["name", "email", "created_date", "status"]


def is_missing(value):
    if value is None:
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def normalise_text(value):
    if is_missing(value):
        return None
    text = str(value).strip()
    return text or None


def normalise_date(value):
    if is_missing(value):
        return None
    text = str(value).strip()
    if text.lower() in {"", "nan", "none", "null", "nat"}:
        return None
    try:
        return pd.to_datetime(text).strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return text


def normalise_status(value):
    """Return a canonical 'active'/'inactive' string, or the raw string."""
    if is_missing(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = str(value).strip()
    low = text.lower()
    if low in {"", "nan", "none", "null"}:
        return None
    if low in {"true", "1", "yes", "y", "active"}:
        return "active"
    if low in {"false", "0", "no", "n", "inactive"}:
        return "inactive"
    return text


def read_source(path, kind):
    if kind == "json":
        return pd.read_json(path, dtype=False)
    if kind == "csv":
        return pd.read_csv(path)
    if kind == "parquet":
        return pd.read_parquet(path)
    raise ValueError(f"unsupported source kind: {kind}")


def load_source(path, kind, column_map):
    df = read_source(path, kind).rename(columns=column_map)
    columns = ["user_id"] + [f for f in FIELDS if f in df.columns]
    df = df[columns].copy()

    df["user_id"] = pd.to_numeric(df["user_id"], errors="coerce")
    df = df.dropna(subset=["user_id"])
    df["user_id"] = df["user_id"].astype("int64")

    for field in ("name", "email"):
        if field in df.columns:
            df[field] = df[field].map(normalise_text)
    if "created_date" in df.columns:
        df["created_date"] = df["created_date"].map(normalise_date)
    if "status" in df.columns:
        df["status"] = df["status"].map(normalise_status)

    return df


def main():
    merged = {}       # user_id -> {field: value}
    source_rows = {}  # source name -> {user_id: row}

    # Sources are processed in priority order; the first non-null value wins.
    for source_name, path, kind, column_map in SOURCES:
        df = load_source(path, kind, column_map)
        rows = {}
        for row in df.to_dict("records"):
            user_id = int(row["user_id"])
            rows[user_id] = row
            record = merged.setdefault(user_id, {field: None for field in FIELDS})
            for field in FIELDS:
                if record[field] is None:
                    value = row.get(field)
                    if value is not None:
                        record[field] = value
        source_rows[source_name] = rows

    # Detect field-level conflicts: same user, differing non-null values.
    conflicts = []
    for user_id in sorted(merged):
        for field in FIELDS:
            values = {}
            for source_name, _, _, _ in SOURCES:
                row = source_rows[source_name].get(user_id)
                if row is not None and row.get(field) is not None:
                    values[source_name] = row[field]
            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values,
                        "selected": merged[user_id][field],
                    }
                )

    out = pd.DataFrame(
        [
            {"user_id": user_id, **{f: merged[user_id][f] for f in FIELDS}}
            for user_id in sorted(merged)
        ],
        columns=["user_id"] + FIELDS,
    )
    out["user_id"] = out["user_id"].astype("int64")

    schema = pa.schema(
        [
            ("user_id", pa.int64()),
            ("name", pa.string()),
            ("email", pa.string()),
            ("created_date", pa.string()),
            ("status", pa.string()),
        ]
    )
    table = pa.Table.from_pandas(out, schema=schema, preserve_index=False)
    pq.write_table(table, OUT_PARQUET)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2)
        fh.write("\n")

    print(f"Wrote {len(out)} users to {OUT_PARQUET}")
    print(f"Wrote {len(conflicts)} conflicts to {OUT_CONFLICTS}")


if __name__ == "__main__":
    main()
